	/**
     * Obtener un listado de las raices de escalas de tarifas de concepto.
     * 
     * @param int $idtarifaconcepto  	Identificador de la tarifa de concepto.
     * @return array Listado de las raices de escalas de tarifas de concepto.
     */
    public static function obtenerListadoEscalasTarifaRaiz($idtarifaconcepto) {
		
        //Devolviendo el listado de estructuras escalares en forma de arreglo.
        return Doctrine_Query::create()
				->select('et.idescalatarifa, et.idoperadorcomparacion, oc.denominacion as denomoperador, et.valorinicial, et.valorfinal,
				et.idformacalculo, fc.denominacion as denomformacalculo, et.importe, et.idformula, et.idconceptopdtarifa, et.idestructuraescalar,
				et.valorescalar, et.idpadre, ee.idtipocampo as tipocampo, ee.idnomencladorreferencia as idnomencladorreferencia , ee.lugaresdecimales as lugaresdecimales')
				->from('NomEscalaTarifa et')
				->leftjoin('et.NomOperadorComparacion oc')
				->leftjoin('et.NomFormaCalculo fc')
				->leftjoin('et.NomEstructuraEscalar ee')
                ->where('et.idconceptopdtarifa = ? and et.idpadre is null', array($idtarifaconcepto))
                ->fetchArray();
    }
    
